/**
 * Patent Secretary Theme
 * Hex-based design tokens matching nomos-secretary visual style
 * Primary: #667eea (purple/blue), Secondary: #764ba2 (deep purple)
 */

@layer base {
  :root {
    /* Font Stack - SF Pro Text preferred, Noto Sans KR fallback */
    --font-sans: -apple-system, BlinkMacSystemFont, 'SF Pro Text', 'Noto Sans KR',
      'Apple SD Gothic Neo', sans-serif;
    --font-mono: 'SF Mono', Menlo, Monaco, monospace;

    /* Base Colors */
    --background: #fafbff; /* Very light blue */
    --foreground: #1a1a2e; /* Dark navy */
    --card: #ffffff; /* Pure white */
    --card-foreground: #1a1a2e;
    --popover: #ffffff;
    --popover-foreground: #1a1a2e;

    /* Brand - Primary Purple/Blue (#667eea) */
    --primary: #667eea;
    --primary-foreground: #ffffff;
    --secondary: #f0eeff; /* Very light purple */
    --secondary-foreground: #1a1a2e;
    --muted: #f0eeff;
    --muted-foreground: #64748b;
    --accent: #e8e6f0; /* Light lavender */
    --accent-foreground: #667eea;

    /* Status & UI */
    --destructive: #ef4444;
    --destructive-foreground: #ffffff;
    --border: #e8e6f0; /* Lavender border */
    --input: #e8e6f0;
    --ring: #667eea;

    /* Chart Colors */
    --chart-1: #667eea; /* Primary */
    --chart-2: #764ba2; /* Deep purple */
    --chart-3: #94a3b8; /* Gray */
    --chart-4: #5a6fd6; /* Deeper blue */
    --chart-5: #d4d0e8; /* Light purple */

    /* Border Radius */
    --radius: 0.5rem; /* 8px */

    /* Sidebar - Glassmorphism */
    --sidebar: rgba(255, 255, 255, 0.7);
    --sidebar-foreground: #1a1a2e;
    --sidebar-primary: #667eea;
    --sidebar-primary-foreground: #ffffff;
    --sidebar-accent: rgba(102, 126, 234, 0.08);
    --sidebar-accent-foreground: #667eea;
    --sidebar-border: rgba(232, 230, 240, 0.5);
    --sidebar-ring: #667eea;

    /* File Type Colors (from nomos-secretary) */
    --color-dt-data: #667eea;
    --color-dt-doc: #667eea;
    --color-dt-email: #0ea5e9; /* Sky blue */
    --color-dt-excel: #217346; /* Green */
    --color-dt-hwp: #2b6cb0; /* Blue */
    --color-dt-image: #7c3aed; /* Purple */
    --color-dt-pdf: #dc2626; /* Red */
    --color-dt-ppt: #d24726; /* Orange */
    --color-dt-task: #16a34a; /* Green */
    --color-dt-word: #2b579a; /* Deep blue */

    /* Status Colors (iOS style) */
    --color-success: #22c55e;
    --color-warning: #f59e0b;
    --color-error: #ff3b30; /* iOS system red */
    --color-info: #007aff; /* iOS blue */
  }

  .dark {
    --background: #1a1a2e; /* Dark navy */
    --foreground: #fafbff; /* Very light blue */
    --card: #252540;
    --card-foreground: #fafbff;
    --popover: #252540;
    --popover-foreground: #fafbff;

    --primary: #8b9bff; /* Lighter purple for dark mode */
    --primary-foreground: #1a1a2e;
    --secondary: #2a2a45;
    --secondary-foreground: #fafbff;
    --muted: #2a2a45;
    --muted-foreground: #94a3b8;
    --accent: #3a3a55;
    --accent-foreground: #8b9bff;

    --destructive: #ef4444;
    --destructive-foreground: #ffffff;
    --border: #3a3a55;
    --input: #3a3a55;
    --ring: #8b9bff;

    --chart-1: #8b9bff;
    --chart-2: #9a7bc2;
    --chart-3: #64748b;
    --chart-4: #7a8fe6;
    --chart-5: #4a4a65;

    --sidebar: rgba(37, 37, 64, 0.8);
    --sidebar-foreground: #fafbff;
    --sidebar-primary: #8b9bff;
    --sidebar-primary-foreground: #1a1a2e;
    --sidebar-accent: rgba(139, 155, 255, 0.1);
    --sidebar-accent-foreground: #8b9bff;
    --sidebar-border: rgba(58, 58, 85, 0.5);
    --sidebar-ring: #8b9bff;
  }
}

/* Background Gradient (optional) */
body {
  background: linear-gradient(135deg, #fafbff 0%, #f5f3ff 50%, #faf5ff 100%);
}

.dark body {
  background: linear-gradient(135deg, #1a1a2e 0%, #252540 50%, #2a2045 100%);
}

/* Custom Scrollbar (nomos-secretary style) */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  background: rgba(0, 0, 0, 0.15);
  border-radius: 3px;
}

::-webkit-scrollbar-thumb:hover {
  background: rgba(0, 0, 0, 0.25);
}

.dark ::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.15);
}

.dark ::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.25);
}
